pub const INVALID_HWID: u64 = u64::MAX;
pub const MPIDR_UP_BITMASK: u64 = 0x1 << 30;
pub const MPIDR_MT_BITMASK: u64 = 0x1 << 24;
pub const MPIDR_HWID_BITMASK: u64 = 0xff00ffffff;
pub const MPIDR_LEVEL_BITS_SHIFT: u32 = 3;
pub const MPIDR_LEVEL_BITS: u32 = 1 << MPIDR_LEVEL_BITS_SHIFT;
pub const MPIDR_LEVEL_MASK: u32 = (1 << MPIDR_LEVEL_BITS) - 1;

pub const fn MPIDR_LEVEL_SHIFT(level: u32) -> u32 { (((1 << level) >> 1) << MPIDR_LEVEL_BITS_SHIFT) }
pub const fn MPIDR_AFFINITY_LEVEL(mpidr: u64, level: u32) -> u64 { (mpidr >> MPIDR_LEVEL_SHIFT(level)) & MPIDR_LEVEL_MASK as u64 }
pub const MIDR_REVISION_MASK: u32 = 0xf;
pub const fn MIDR_REVISION(midr: u32) -> u32 { midr & MIDR_REVISION_MASK }
pub const MIDR_PARTNUM_SHIFT: u32 = 4;
pub const MIDR_PARTNUM_MASK: u32 = 0xfff << MIDR_PARTNUM_SHIFT;
pub const fn MIDR_PARTNUM(midr: u32) -> u32 { (midr & MIDR_PARTNUM_MASK) >> MIDR_PARTNUM_SHIFT }
pub const MIDR_ARCHITECTURE_SHIFT: u32 = 16;
pub const MIDR_ARCHITECTURE_MASK: u32 = 0xf << MIDR_ARCHITECTURE_SHIFT;
pub const fn MIDR_ARCHITECTURE(midr: u32) -> u32 { (midr & MIDR_ARCHITECTURE_MASK) >> MIDR_ARCHITECTURE_SHIFT }
pub const MIDR_VARIANT_SHIFT: u32 = 20;
pub const MIDR_VARIANT_MASK: u32 = 0xf << MIDR_VARIANT_SHIFT;
pub const fn MIDR_VARIANT(midr: u32) -> u32 { (midr & MIDR_VARIANT_MASK) >> MIDR_VARIANT_SHIFT }
pub const MIDR_IMPLEMENTOR_SHIFT: u32 = 24;
pub const MIDR_IMPLEMENTOR_MASK: u32 = 0xff << MIDR_IMPLEMENTOR_SHIFT;
pub const fn MIDR_IMPLEMENTOR(midr: u32) -> u32 { (midr & MIDR_IMPLEMENTOR_MASK) >> MIDR_IMPLEMENTOR_SHIFT }
pub const fn MIDR_CPU_MODEL(imp: u32, partnum: u32) -> u32 { (imp << MIDR_IMPLEMENTOR_SHIFT) | (0xf << MIDR_ARCHITECTURE_SHIFT) | (partnum << MIDR_PARTNUM_SHIFT) }
pub const fn MIDR_CPU_VAR_REV(var_: u32, rev: u32) -> u32 { (var_ << MIDR_VARIANT_SHIFT) | rev }
pub const MIDR_CPU_MODEL_MASK: u32 = MIDR_IMPLEMENTOR_MASK | MIDR_PARTNUM_MASK | MIDR_ARCHITECTURE_MASK;

